/**
 * SocialLinks — compact row of social icon buttons.
 *
 * Used in the navbar, footer and blog pages. Links are placeholders the
 * site owner can swap later by editing SOCIAL_URLS below.
 *
 * `variant` controls the visual weight:
 *  - "compact" → small icon-only buttons for the navbar
 *  - "default" → medium icon buttons for the footer
 *  - "inline"  → text+icon links for blog share bars
 */

// URLs come from env (NEXT_PUBLIC_* is inlined at build time — redeploy to
// apply a change); the literals are only fallbacks.
export const SOCIAL_URLS = {
	instagram:
		process.env.NEXT_PUBLIC_INSTAGRAM_URL || 'https://instagram.com/vigent_ir',
	telegram: process.env.NEXT_PUBLIC_TELEGRAM_URL || 'https://t.me/vigent_ir',
} as const

const SOCIAL_LABELS = {
	instagram: 'اینستاگرام',
	telegram: 'تلگرام',
} as const

export function SocialLinks({
	variant = 'default',
	className,
}: {
	variant?: 'compact' | 'default' | 'inline'
	className?: string
}) {
	const links = [
		{
			href: SOCIAL_URLS.instagram,
			label: SOCIAL_LABELS.instagram,
			Icon: InstagramIcon,
		},
		{
			href: SOCIAL_URLS.telegram,
			label: SOCIAL_LABELS.telegram,
			Icon: TelegramIcon,
		},
	]

	if (variant === 'inline') {
		return (
			<div className={cn('flex items-center gap-3', className)}>
				{links.map(({ href, label, Icon }) => (
					<a
						key={href}
						href={href}
						target="_blank"
						rel="noopener noreferrer"
						className="inline-flex min-h-11 items-center gap-1.5 text-xs text-[var(--text-secondary)] transition-colors hover:text-[var(--text-primary)]"
					>
						<Icon className="h-4 w-4" />
						{label}
					</a>
				))}
			</div>
		)
	}

	const btn =
		variant === 'compact'
			? 'h-11 w-11 rounded-xl border border-[var(--border-default)] text-[var(--text-secondary)] hover:border-[var(--border-hover)] hover:text-[var(--text-primary)]'
			: 'h-11 w-11 rounded-full border border-[var(--border-default)] text-[var(--text-secondary)] hover:border-[var(--border-hover)] hover:text-[var(--text-primary)]'

	const iconSize = variant === 'compact' ? 'h-4 w-4' : 'h-[18px] w-[18px]'

	return (
		<div className={cn('flex items-center gap-2', className)}>
			{links.map(({ href, label, Icon }) => (
				<a
					key={href}
					href={href}
					target="_blank"
					rel="noopener noreferrer"
					aria-label={label}
					title={label}
					className={cn('inline-flex items-center justify-center transition-colors', btn)}
				>
					<Icon className={iconSize} />
				</a>
			))}
		</div>
	)
}
